<script>
  function filterServices() {
    const searchQuery = (document.getElementById('searchInput')?.value || '').toLowerCase().trim();
    const categoryQuery = document.getElementById('categoryFilter')?.value || 'ALL';
    const cityQuery = document.getElementById('cityFilter')?.value || 'ALL';
    const cards = document.querySelectorAll('.service-card');
    let visibleCount = 0;

    cards.forEach(card => {
      const cardTitle = card.querySelector('h3')?.innerText.toLowerCase() || '';
      const cardMeta = card.innerText.toLowerCase();
      const cardCategory = card.getAttribute('data-category') || '';
      const cardType = card.getAttribute('data-type') || '';
      const cardMode = card.getAttribute('data-mode') || '';

      const matchesSearch = !searchQuery || cardTitle.includes(searchQuery) || cardMeta.includes(searchQuery);
      const matchesCategory = (categoryQuery === 'ALL') || (cardCategory === categoryQuery);
      
      let matchesCity = true;
      if (cityQuery !== 'ALL') {
        matchesCity = cardMeta.includes(cityQuery.toLowerCase()) || cardMeta.includes('seluruh') || cardMeta.includes('indonesia');
      }

      if (matchesSearch && matchesCategory && matchesCity) {
        card.style.display = 'flex';
        visibleCount++;
      } else {
        card.style.display = 'none';
      }
    });

    const resultLabel = document.getElementById('resultCount');
    if (resultLabel) {
      resultLabel.innerText = `MENAMPILKAN ${visibleCount} PROGRAM DISETUJUI`;
    }
  }

  function setQuickTag(tag) {
    const searchInput = document.getElementById('searchInput');
    const categoryFilter = document.getElementById('categoryFilter');
    if (!searchInput || !categoryFilter) return;

    if (tag === 'ALL') {
      searchInput.value = '';
      categoryFilter.value = 'ALL';
    } else if (tag === 'Kemnaker RI') {
      searchInput.value = 'Kemnaker';
    } else if (tag === 'BNSP') {
      searchInput.value = 'BNSP';
    } else if (tag === 'Blended') {
      searchInput.value = 'Blended';
    }
    filterServices();
  }

  document.getElementById('searchInput')?.addEventListener('input', filterServices);
  document.getElementById('categoryFilter')?.addEventListener('change', filterServices);
  document.getElementById('cityFilter')?.addEventListener('change', filterServices);
